wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts Unix seconds (UTC) to a `YYYY-MM-DD` string.
/// Uses the civil-from-days algorithm; no dependencies required.
fn civil_date(unix_seconds: u64) -> String {
    let days = unix_seconds / 86_400;
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        RunInfo {
            date: civil_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
